interface ApiResponse<T> {
    data: T;
    status: number;
    message: string;
    totalRecords?:number;
}
export type QuestionItem = {
  id: number;
  question: string;
  answer: string;
  rating: number | null;
  header?: string;
};
import { IQuestionnaireApi } from "./IQuestionnaireApi";

export default class QuestionnaireApi implements IQuestionnaireApi {


  async getQuestionnaire(jobCode: string): Promise<ApiResponse<QuestionItem[] | null>> {
    try {
      const response = await InterViewQuesAPI.GetQuestionnaire(jobCode);
      const GetQuestionnaire: QuestionItem[] = response.data.data.map((item: any, index: number) => {
        const incrementedIndex = index + 1;
        return {
          id: incrementedIndex,
          question: item?.question?.quesContent?.contentEn,
          questionFr: item?.question?.quesContent?.contentFr,
          answer: item?.question?.questionXAnswers?.[0]?.optContent?.contentEn ?? "",
          answerFr: item?.question?.questionXAnswers?.[0]?.optContent?.contentFr ?? "",
          rating: 0,
          header: "Q" + incrementedIndex,
        };
      });
      // console.log(response, "GetAllMasterData");
      return {
        data: GetQuestionnaire,
        status: response.status,
        message: "Get Candidate details",
      };
    } catch (error) {
      console.error(
        "Error Get Candidate details:",
        error
      );
      return {
        data: [],
        status: 500,
        message: "Error Get Candidate details",
      };
    }
  }





}
